package main
import("os";"fmt";"syscall";"encoding/json";"encoding/hex";"crypto/sha256";"strconv";"path/filepath";"strings")
func op(h syscall.Handle,code uint32,n int,nonce uint64,count uint32)([]byte,error){q:=make([]byte,32);le.PutUint32(q,32);le.PutUint32(q[4:],1);copy(q[8:],[]byte("OG99KEY1"));le.PutUint64(q[16:],nonce);le.PutUint32(q[24:],count);b:=make([]byte,n);var got uint32;e:=syscall.DeviceIoControl(h,code,&q[0],32,&b[0],uint32(n),&got,nil);if e!=nil{return nil,e};if got!=uint32(n){return nil,fmt.Errorf("short result %d",got)};return b,nil}
func main(){result:=map[string]any{"ok":false,"sample_submitted":false};defer func(){if e:=recover();e!=nil{result["error"]=fmt.Sprint(e)};json.NewEncoder(os.Stdout).Encode(result);if result["ok"]!=true{os.Exit(1)}}();must:=func(e error){if e!=nil{panic(e)}};must(fullOSGuard());if len(os.Args)<2{panic("status | sample count nonce16 path | result nonce16 path")};mode:=os.Args[1];n:=uint64(0);count:=uint64(0);path:="";nonceText:=""
 if (mode=="status"||mode=="bus"){if len(os.Args)!=2{panic("status arguments")}}else if mode=="sample"{if len(os.Args)!=5{panic("sample arguments")};var e error;count,e=strconv.ParseUint(os.Args[2],10,32);must(e);if count<1||count>1024{panic("sample count")};nonceText=os.Args[3];path=os.Args[4]}else if mode=="result"{if len(os.Args)!=4{panic("result arguments")};nonceText=os.Args[2];path=os.Args[3]}else{panic("unknown mode")}
 if mode!="status"&&mode!="bus"{var e error;n,e=strconv.ParseUint(nonceText,16,64);must(e);if len(nonceText)!=16||n==0||strings.ToLower(nonceText)!=nonceText{panic("nonce")};base:=`C:\OpenG81\payloads`;want:="G100-result-"+nonceText+".bin";recovered:="G100-result-"+nonceText+"-recovered.bin";if !strings.EqualFold(filepath.Dir(path),base)||(filepath.Base(path)!=want&&filepath.Base(path)!=recovered){panic("exclusive project result path")}}
 ptr,_:=syscall.UTF16PtrFromString(`\\.\OpenG100Keys`);h,e:=syscall.CreateFile(ptr,syscall.GENERIC_READ|syscall.GENERIC_WRITE,0,nil,syscall.OPEN_EXISTING,0,0);must(e);defer syscall.CloseHandle(h)
 if mode=="bus"{b,e:=op(h,0x22680c,56,0,0);must(e);if le.Uint32(b)!=56||le.Uint32(b[4:])!=1{panic("bus ABI")};v:=map[string]any{};for i,n:=range []string{"ready","poisoned","owners","peak_owners"}{v[n]=le.Uint32(b[8+4*i:])};for i,n:=range []string{"acquires","releases","timeouts","denied"}{v[n]=le.Uint64(b[24+8*i:])};result["bus"]=v;result["ok"]=true;return}
 b,e:=op(h,0x226800,80,0,0);must(e);s,e:=decodeStatus(b);must(e);result["status_before"]=s;if (mode=="status"||mode=="bus"){result["ok"]=true;return};if s["kernel_build"]!=uint32(26300)||s["processors"]!=uint32(8)||s["IRQL"]!=uint32(0)||s["firmware_match"]!=uint32(1)||s["firmware_bytes"]!=uint32(576){panic("qualified platform required")};if mode=="sample"&&(s["attempts"]!=uint32(0)||s["map_calls"]!=uint32(0)){panic("owner consumed: observe frozen result")}
 f,e:=os.OpenFile(path,os.O_CREATE|os.O_EXCL|os.O_WRONLY,0600);must(e);defer f.Close();code:=uint32(0x226808);if mode=="sample"{code=0x22e804;result["sample_submitted"]=true};b,e=op(h,code,captureBytes,n,uint32(count));must(e);_,e=f.Write(b);must(e);must(f.Sync());must(f.Close());sum:=sha256.Sum256(b);result["path"]=path;result["bytes"]=len(b);result["sha256"]=hex.EncodeToString(sum[:]);v,e:=decodeCapture(b,n);must(e);result["result"]=v;result["ok"]=true
}
